import "server-only";

/**
 * Fontes da marca (Cormorant Garamond, Barlow) embutidas como base64 para uso
 * exclusivo no motor de PDF de propostas (CRM Fase B2). Diferente do resto do
 * app — que auto-hospeda via next/font (ver apps/cms/src/app/fonts.ts) — esta
 * geração roda no servidor via Playwright/Chromium e NÃO pode depender de um
 * <link> para fonts.googleapis.com em runtime (CLAUDE.md §3: "Não importe
 * outras fontes" + risco real de timeout/fallback para Helvetica no
 * page.setContent() se o CDN estiver lento/bloqueado). Os 5 arquivos abaixo
 * cobrem exatamente os pesos/estilos usados em html.ts (grep por
 * font-family/font-weight/font-style confirmou o conjunto):
 *   - Cormorant Garamond 400 normal (destinatario da capa, texto sem peso
 *     explícito herda 400)
 *   - Cormorant Garamond 600 normal (h1/h2/h3, brand/titulo da capa,
 *     .box .value, <strong> dentro da capa)
 *   - Barlow 400 normal (corpo do documento)
 *   - Barlow 600 normal (<strong>, .box .label, linha de total do quadro)
 *   - Barlow 400 italic (célula "Item único" de secaoQuadroComercial, que
 *     tem font-style:italic inline sem font-family própria — herda Barlow
 *     do body)
 *
 * cormorant-garamond-400.woff2 e cormorant-garamond-600.woff2 são bytes
 * IDÊNTICOS — a Google serve essa família como um único arquivo (variable
 * font) para a faixa 400–600 nesse subset; o Chromium seleciona a instância
 * correta a partir do font-weight declarado em cada @font-face. Isso é
 * comportamento normal do endpoint css2 da Google Fonts, não um erro de
 * download (confirmado via curl com UA de Chrome — ambas as URLs retornadas
 * pela API são a mesma).
 *
 * Baixados de fonts.gstatic.com em 2026-08-29, subset "latin" (suficiente:
 * U+0000-00FF cobre todos os acentos do português — ã, ç, õ etc. — sem
 * precisar do subset latin-ext, usado para outras línguas latinas).
 * Arquivos-fonte em ./fonts/*.woff2 (versionados) — este arquivo é a
 * codificação base64 gerada a partir deles, para não depender de leitura de
 * disco em runtime (precisa funcionar igual em dev e na Vercel serverless).
 */

export const CORMORANT_GARAMOND_400_BASE64 = "";
export const CORMORANT_GARAMOND_600_BASE64 = "";
export const BARLOW_400_BASE64 = "";
export const BARLOW_600_BASE64 = "";
export const BARLOW_400_ITALICO_BASE64 = "";

/** CSS @font-face pronto, para ser injetado no topo de estilosDocumento(). */
export const FONTES_EMBUTIDAS_CSS = `
@font-face{font-family:'Cormorant Garamond';font-style:normal;font-weight:400;src:url(data:font/woff2;base64,${CORMORANT_GARAMOND_400_BASE64}) format('woff2')}
@font-face{font-family:'Cormorant Garamond';font-style:normal;font-weight:600;src:url(data:font/woff2;base64,${CORMORANT_GARAMOND_600_BASE64}) format('woff2')}
@font-face{font-family:'Barlow';font-style:normal;font-weight:400;src:url(data:font/woff2;base64,${BARLOW_400_BASE64}) format('woff2')}
@font-face{font-family:'Barlow';font-style:normal;font-weight:600;src:url(data:font/woff2;base64,${BARLOW_600_BASE64}) format('woff2')}
@font-face{font-family:'Barlow';font-style:italic;font-weight:400;src:url(data:font/woff2;base64,${BARLOW_400_ITALICO_BASE64}) format('woff2')}
`;
